mapper.select:
SELECT id, task_name, data_source, export_headers, field_mapping, query_condition, estimated_rows, file_name_template, status, DATE_FORMAT(create_time, '%Y-%m-%d %H:%i:%s') as create_time, DATE_FORMAT(update_time, '%Y-%m-%d %H:%i:%s') as update_time, create_by, update_by FROM b_data_export_task
AND task_name LIKE CONCAT('%', #{taskName}, '%')
AND data_source = #{dataSource}
AND status = #{status}
ORDER BY create_time DESC
